-- Seed N2 — Từ vựng (Mimikara N2), nguồn PDF mojigoi_N2.pdf ("Từ vựng Mimikara N2", 24 trang).
-- Trích xuất TOÀN BỘ 1160 từ theo đúng thứ tự STT 1-1160 trong PDF (bảng: STT | Từ vựng
--   (đọc) | Kanji | Âm Hán | Ý nghĩa). Mapping vào schema thật:
--   - vocabulary.reading = cột "Từ vựng" (hiragana/katakana).
--   - vocabulary.word = cột "Kanji" nếu có giá trị; nếu trống (từ chỉ viết kana, VD ひも, かぶる,
--     hoặc từ mượn katakana như アンテナ) thì word = chính giá trị của reading.
--   - vocabulary_meanings.meaning_vi (order_index=0) = cột "Ý nghĩa".
--   - part_of_speech/audio_url/category: NULL — nguồn không cung cấp, không tự bịa.
--   - example_jp/example_vi: NULL — nguồn không có câu ví dụ.
--   - Cột "Âm Hán" (đọc Hán Việt) trong PDF: BỎ QUA — bảng vocabulary không có cột tương ứng,
--     không tự chế thêm cột, không nối vào meaning_vi.
-- Giới hạn/ghi chú đã biết:
--   - Dòng #1153 (じっさい／実際／"THỰC TẾ"): cột Ý nghĩa trong nguồn PDF ghi "tình cờ, thỉnh
--     thoảng" — trùng y hệt nghĩa của dòng #1152 (たまたま). Nhiều khả năng là lỗi copy-paste
--     trong bản gốc PDF (thực tế 実際 nghĩa là "thực tế, trên thực tế"), nhưng vì yêu cầu không tự
--     bịa nội dung không có trong nguồn nên giữ nguyên đúng như PDF, không tự sửa.
--   - Một số từ trong nguồn có nhiều cách viết kanji cho cùng 1 từ (VD 単純な/純粋な, 戦う/闘う,
--     沿う・添う...) — giữ nguyên đúng như cột Kanji của PDF (có thể chứa dấu "・" hoặc "/").
--   - Không có dòng nào bị mờ/không đọc được trong 24 trang đã đọc.
-- lessons: chia 15 từ liên tiếp theo đúng thứ tự PDF = 1 "ngày" học, không gắn giáo trình cụ thể
--   (tổng 78 lesson cho 1160 từ, ngày cuối có 5 từ).
--   order_index bắt đầu từ 2001 để không đụng order_index của lesson ngữ pháp (1-52)/kanji (1001+) N2.
-- Idempotent: UUID cố định (uuid5 theo nội dung: "app-nihongo:n2:vocab:<reading>:<word>" và
--   "app-nihongo:n2:lesson:vocab:day:<NNN>"), on conflict do nothing — chạy lại an toàn.
--
-- Chạy: supabase db query --linked -f supabase/seed_content_n2_vocab.sql

